fn is_happy(s: Vec<char>) -> bool {
    // A "happy" sequence must have at least 3 characters
    if s.len() < 3 {
        return false;
    }

    // Check every contiguous window of length 3
    for window in s.windows(3) {
        // If any two characters in the window are the same, it's not happy
        if window[0] == window[1]
            || window[0] == window[2]
            || window[1] == window[2]
        {
            return false;
        }
    }

    // If all windows passed the distinctness check, it's happy
    true
}

